#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int countLocalMaximums(std::vector<std::vector<int>>& matrix) {
        int n = matrix.size();
        int m = matrix[0].size();
        int ans = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                int x = matrix[r][c];
                if (x == 0) continue;
                bool isMax = true;
                int rMin = std::max(0, r - x);
                int rMax = std::min(n - 1, r + x);
                int cMin = std::max(0, c - x);
                int cMax = std::min(m - 1, c + x);
                for (int nr = rMin; nr <= rMax; ++nr) {
                    for (int nc = cMin; nc <= cMax; ++nc) {
                        if (std::abs(nr - r) == x && std::abs(nc - c) == x) continue;
                        if (matrix[nr][nc] > x) {
                            isMax = false;
                            break;
                        }
                    }
                    if (!isMax) break;
                }
                if (isMax) ans++;
            }
        }
        return ans;
    }
};

